add_action( 'wp_head', 'perfectpixel_css_for_specific_url', 99 );

function perfectpixel_css_for_specific_url() {
	$needle = trim( '{{css_url_contains}}' );
	$uri    = isset( $_SERVER['REQUEST_URI'] ) ? wp_unslash( $_SERVER['REQUEST_URI'] ) : '';
	if ( '' === $needle || false === strpos( rawurldecode( $uri ), $needle ) ) {
		return;
	}
	// Strip tags so the CSS cannot close the <style> element.
	echo '<style id="perfectpixel-url-css">' . wp_strip_all_tags( '{{css_url_rules}}' ) . '</style>';
}
